solucao.estilo.css:
.item {
  background-color: #f1f5f9;
}

.raro {
  color: darkorchid;
  font-weight: bold;
}

#saldo {
  color: seagreen;
}

.aviso {
  background-color: lightyellow;
}

h1, h2 {
  color: #7c2d12;
}

header p {
  font-style: italic;
}

h2 + p {
  font-weight: bold;
}

.dicas > p {
  border-left: 4px solid #7c2d12;
}

nav a {
  color: navy;
}

nav a:visited {
  color: purple;
}

nav a:hover {
  background-color: navy;
  color: white;
}

input:focus {
  outline: 3px solid orange;
}

button:active {
  background-color: darkorange;
}

.ranking li:nth-child(even) {
  background-color: #f1f5f9;
}

.ranking li:first-child {
  color: darkgoldenrod;
  font-weight: bold;
}

.ranking li:nth-child(3) {
  color: sienna;
}

.ranking li:last-child {
  color: gray;
}

.feita::before {
  content: "✓ ";
  color: green;
}

.moedas::after {
  content: " moedas";
}

.intro::first-letter {
  font-size: 40px;
  color: darkred;
}

