solucao.estilo.css:
/* Tema da página (pronto) */
body {
  margin: 0;
  font-family: Verdana, sans-serif;
  color: #1e293b;
}

.topo {
  background-color: #0f172a;
  padding: 12px 20px;
}

.marca {
  margin: 0 0 8px;
  color: white;
  font-weight: bold;
}

main {
  padding: 0 20px;
}

/* O menu: escreva as regras abaixo */
.menu a {
  display: inline-block;
  padding: 8px 14px;
  color: #e2e8f0;
  text-decoration: none;
}

.menu a:hover,
.menu a:focus {
  background-color: #334155;
  color: white;
}

.menu a.ativo {
  background-color: darkorange;
  color: #0f172a;
}

.menu a:last-child {
  border: 2px solid darkorange;
  border-radius: 6px;
}

.menu a:last-child::after {
  content: " →";
}
